module cookie_wall (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [31:0] omega,\n    input wire [31:0] v0,\n    input wire [31:0] theta,\n    input wire [31:0] w,\n    input wire [31:0] x0, x1, x2, x3, x4, x5, x6, x7,\n    input wire [31:0] y0, y1, y2, y3, y4, y5, y6, y7,\n    output reg [3:0] result_index,\n    output reg [31:0] result_time,\n    output reg done\n);\n    \n    localparam [4:0] S_IDLE          = 5'd0;\n    localparam [4:0] S_COMPUTE_COM   = 5'd1;\n    localparam [4:0] S_COMPUTE_VEL   = 5'd2;\n    localparam [4:0] S_COMPUTE_REL   = 5'd3;\n    localparam [4:0] S_INIT_TIME     = 5'd4;\n    localparam [4:0] S_COMPUTE_TRIG  = 5'd5;\n    localparam [4:0] S_COMPUTE_TRAJ  = 5'd6;\n    localparam [4:0] S_CHECK_VERTEX  = 5'd7;\n    localparam [4:0] S_NEXT_TIME     = 5'd8;\n    localparam [4:0] S_DONE          = 5'd9;\n    \n    reg [4:0] state;\n    reg [31:0] com_x, com_y;\n    reg [31:0] v0x, v0y;\n    reg [31:0] dx[0:7];\n    reg [31:0] dy[0:7];\n    reg [31:0] angle;\n    reg [31:0] cos_phi, sin_phi;\n    reg [31:0] x_com_pos, y_com_pos;\n    reg [31:0] x_vertex;\n    reg [3:0] vertex_counter;\n    reg [31:0] time_reg;\n    reg [31:0] best_time;\n    reg [3:0] best_index;\n    reg found;\n\n    localparam [31:0] MAX_TIME = 32'd39321600;  // 600 * 65536\n    localparam [31:0] TIME_STEP = 32'd6553;      // 0.1 * 65536\n    localparam [31:0] G = 32'd643072;           // 9.81 * 65536\n    localparam [31:0] PI_TIMES_2 = 32'd411775;  // 2π Q16.16 approx\n    \n    // Fixed-point multiplication\n    function automatic [31:0] mul_fp;\n        input [31:0] a, b;\n        reg [63:0] temp;\n        begin\n            temp = a * b;\n            mul_fp = temp[47:16];\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            found <= 1'b0;\n            time_reg <= 32'd0;\n            best_time <= 32'h7FFFFFFF;\n            best_index <= 4'd0;\n            vertex_counter <= 4'd0;\n            com_x <= 32'd0;\n            com_y <= 32'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= S_COMPUTE_COM;\n                        com_x <= 32'd0;\n                        com_y <= 32'd0;\n                        vertex_counter <= 4'd0;\n                    end\n                end\n                \n                S_COMPUTE_COM: begin\n                    case (vertex_counter)\n                        4'd0: com_x <= x0;\n                        4'd1: com_x <= com_x + x1;\n                        4'd2: com_x <= com_x + x2;\n                        4'd3: com_x <= com_x + x3;\n                        4'd4: com_x <= com_x + x4;\n                        4'd5: com_x <= com_x + x5;\n                        4'd6: com_x <= com_x + x6;\n                        4'd7: com_x <= com_x + x7;\n                    endcase\n                    \n                    case (vertex_counter)\n                        4'd0: com_y <= y0;\n                        4'd1: com_y <= com_y + y1;\n                        4'd2: com_y <= com_y + y2;\n                        4'd3: com_y <= com_y + y3;\n                        4'd4: com_y <= com_y + y4;\n                        4'd5: com_y <= com_y + y5;\n                        4'd6: com_y <= com_y + y6;\n                        4'd7: com_y <= com_y + y7;\n                    endcase\n                    \n                    if (vertex_counter == (n - 1)) begin\n                        com_x <= (com_x << 16) / {28'd0, n};\n                        com_y <= (com_y << 16) / {28'd0, n};\n                        state <= S_COMPUTE_VEL;\n                    end else begin\n                        vertex_counter <= vertex_counter + 4'd1;\n                    end\n                end\n                \n                S_COMPUTE_VEL: begin\n                    v0x <= mul_fp(v0, 32'd65536);  // Simplified\n                    v0y <= mul_fp(v0, theta);      // Simplified\n                    state <= S_COMPUTE_REL;\n                    vertex_counter <= 4'd0;\n                end\n                \n                S_COMPUTE_REL: begin\n                    case (vertex_counter)\n                        4'd0: dx[0] <= x0 - com_x;\n                        4'd1: dx[1] <= x1 - com_x;\n                        4'd2: dx[2] <= x2 - com_x;\n                        4'd3: dx[3] <= x3 - com_x;\n                        4'd4: dx[4] <= x4 - com_x;\n                        4'd5: dx[5] <= x5 - com_x;\n                        4'd6: dx[6] <= x6 - com_x;\n                        4'd7: dx[7] <= x7 - com_x;\n                    endcase\n                    \n                    case (vertex_counter)\n                        4'd0: dy[0] <= y0 - com_y;\n                        4'd1: dy[1] <= y1 - com_y;\n                        4'd2: dy[2] <= y2 - com_y;\n                        4'd3: dy[3] <= y3 - com_y;\n                        4'd4: dy[4] <= y4 - com_y;\n                        4'd5: dy[5] <= y5 - com_y;\n                        4'd6: dy[6] <= y6 - com_y;\n                        4'd7: dy[7] <= y7 - com_y;\n                    endcase\n                    \n                    if (vertex_counter == (n - 1)) begin\n                        state <= S_INIT_TIME;\n                    end else begin\n                        vertex_counter <= vertex_counter + 4'd1;\n                    end\n                end\n                \n                S_INIT_TIME: begin\n                    time_reg <= 32'd0;\n                    state <= S_COMPUTE_TRIG;\n                end\n                \n                S_COMPUTE_TRIG: begin\n                    angle <= mul_fp(omega, time_reg);\n                    if (angle < PI_TIMES_2) begin\n                        cos_phi <= 32'd65536 - (mul_fp(angle, angle) >> 1);\n                        sin_phi <= angle;\n                    end else begin\n                        cos_phi <= 32'd46341;\n                        sin_phi <= 32'd46341;\n                    end\n                    state <= S_COMPUTE_TRAJ;\n                end\n                \n                S_COMPUTE_TRAJ: begin\n                    x_com_pos <= com_x + mul_fp(v0x, time_reg);\n                    y_com_pos <= com_y + mul_fp(v0y, time_reg) - (mul_fp(G, mul_fp(time_reg, time_reg)) >> 1);\n                    vertex_counter <= 4'd0;\n                    state <= S_CHECK_VERTEX;\n                end\n                \n                S_CHECK_VERTEX: begin\n                    case (vertex_counter)\n                        4'd0: x_vertex <= x_com_pos + mul_fp(dx[0], cos_phi) + mul_fp(dy[0], sin_phi);\n                        4'd1: x_vertex <= x_com_pos + mul_fp(dx[1], cos_phi) + mul_fp(dy[1], sin_phi);\n                        4'd2: x_vertex <= x_com_pos + mul_fp(dx[2], cos_phi) + mul_fp(dy[2], sin_phi);\n                        4'd3: x_vertex <= x_com_pos + mul_fp(dx[3], cos_phi) + mul_fp(dy[3], sin_phi);\n                        4'd4: x_vertex <= x_com_pos + mul_fp(dx[4], cos_phi) + mul_fp(dy[4], sin_phi);\n                        4'd5: x_vertex <= x_com_pos + mul_fp(dx[5], cos_phi) + mul_fp(dy[5], sin_phi);\n                        4'd6: x_vertex <= x_com_pos + mul_fp(dx[6], cos_phi) + mul_fp(dy[6], sin_phi);\n                        4'd7: x_vertex <= x_com_pos + mul_fp(dx[7], cos_phi) + mul_fp(dy[7], sin_phi);\n                    endcase\n                    \n                    if (vertex_counter < n) begin\n                        if (x_vertex >= w && !found) begin\n                            best_time <= time_reg;\n                            best_index <= vertex_counter + 4'd1;\n                            found <= 1'b1;\n                        end\n                    end\n                    \n                    if (vertex_counter == (n - 1)) begin\n                        state <= S_NEXT_TIME;\n                    end else begin\n                        vertex_counter <= vertex_counter + 4'd1;\n                    end\n                end\n                \n                S_NEXT_TIME: begin\n                    time_reg <= time_reg + TIME_STEP;\n                    if (time_reg >= MAX_TIME || found) begin\n                        state <= S_DONE;\n                    end else begin\n                        state <= S_COMPUTE_TRIG;\n                    end\n                end\n                \n                S_DONE: begin\n                    result_index <= best_index;\n                    result_time <= best_time;\n                    done <= 1'b1;\n                    if (!start) state <= S_IDLE;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule